function genDefaultReadme(values) {
  var publications = values.primaryPublications.map(function (publication) {
    return publication.title;
  }).join(', ');
  var identifier = values.identifier.identifier || '';
  var functionsAssessed = values.experimentsFunctionAssessed.join(', ');
  var languages = values.experimentsLanguages.join(', ');
  var validationMeasures = values.experimentsValidationMeasures.join(', ');
  var validationPopulations = values.experimentsValidationPopulations.join(', ');
  var licenses = values.licenses.join(', ');
  var accessibility = values.experimentsAccessibility.join(', ');
  var modalities = values.experimentsModalities.join(', ');
  var devices = values.experimentsRequiredDevices.join(', ');
  var software = values.experimentsRequiredSoftware.map(function (value) {
    return value.software + " version " + value.version;
  }).join(', ');
  return "# " + values.title + "\n\n" + values.description + "\n\n**Publication:** " + publications + "\n\n**Experiment DOI:** " + identifier + "\n\n**Functions assessed:** " + functionsAssessed + "\n\n## Features\n\n**Languages:** " + languages + "\n\n**Validation:**\n  * Measures: " + validationMeasures + "\n  * Populations: " + validationPopulations + "\n\n**Accessibility:** " + accessibility + "\n\n**Modalities:** " + modalities + "\n\n**Devices:** " + devices + "\n\n**Species:** " + values.isAbout.map(function (isAbout) {
    return isAbout.name;
  }).join(', ') + "\n\n## Development\n\n**Software:** " + software + "\n\n**Requirements:** " + values.experimentsAdditionalRequirements + "\n\n## Administration\n\n## Procedure and Conditions\n\n## Output Files\n\n## Scoring\n\n## Additional Features\n\n## Planned Features\n\n## How to Contribute\n\n## Contributors\n\n## License and Attribution\n\n**License:** " + licenses + "\n\n## Additional Reading\n";
}
